def region(layer):
 s=(ROOT/'sources'/LAYERS[layer]).read_text();a=s.index(anchor);b=s.index(r'\end{illusiebodypage}',a);return s[a:b]
def ch(layer,old,new,line,sid,why,kind='typesetting'):edit_page(layer,anchor,old,new,page,line,sid,ev+why,kind)
old=region('corrected');new=old.replace('sur $P$,','sur $P$ ,').replace('sur $A$, et','sur $A$ , et').replace('sur $Q$,','sur $Q$ ,').replace('à $C$,','à $C$ ,').replace(r'$L^{\Delta}_{C/B/A}$.',r'$L^{\Delta}_{C/B/A}$ .')
